  "characters[char-tenten].name": "Tenten",
  "characters[char-sai].name": "Sai",
  "characters[char-yamato].name": "Yamato",
  "characters[char-konohamaru].name": "Konohamaru Sarutobi",
  "characters[char-iruka].name": "Iruka Umino",
  "characters[char-guy].name": "Might Guy",
  "characters[char-asuma].name": "Asuma Sarutobi",
  "characters[char-kurenai].name": "Kurenai Yuhi",
  "characters[char-anko].name": "Anko Mitarashi",
  "characters[char-shizune].name": "Shizune",
  "characters[char-ebisu].name": "Ebisu",
  "characters[char-ibiki].name": "Ibiki Morino",
