  "characters[char-shikamaru].abilities[1]": "Técnica de Estrangulamiento de Sombras",
  "characters[char-choji].rank": "Jonin",
  "characters[char-choji].shortDescription": "Especialista en técnicas de expansión corporal. Parte del trío Ino-Shika-Chō.",
  "characters[char-choji].abilities[0]": "Técnica del Tamaño Múltiple",
  "characters[char-choji].abilities[1]": "Control de Calorías",
  "characters[char-choji].abilities[2]": "Modo Mariposa",
  "characters[char-ino].rank": "Jonin",
  "characters[char-ino].shortDescription": "Experta en técnicas mentales, parte del trío Ino-Shika-Chō.",
  "characters[char-ino].abilities[0]": "Técnica de Transferencia de Mente y Cuerpo",
  "characters[char-ino].abilities[1]": "Telepatía",
  "characters[char-ino].abilities[2]": "Ninjutsu médico",
  "characters[char-kiba].rank": "Jonin",
  "characters[char-kiba].shortDescription": "Combate en tándem con el perro ninja Akamaru.",
  "characters[char-kiba].abilities[0]": "Imitación Bestial",
  "characters[char-kiba].abilities[1]": "Colmillo sobre Colmillo",
  "characters[char-hinata].rank": "Chunin / Jonin",
  "characters[char-hinata].shortDescription": "Heredera del clan Hyūga. Enamorada de Naruto desde la infancia.",
  "characters[char-hinata].abilities[0]": "Byakugan",
  "characters[char-hinata].abilities[1]": "Puño Suave",
  "characters[char-hinata].abilities[2]": "Puños Gemelos de León",
