  "characters[char-izuna].abilities[0]": "Mangekyō Sharingan",
  "characters[char-izuna].kekkeiGenkai[0]": "Sharingan",
  "characters[char-izuna].longDescription": "Hermano menor de Madara, con quien comparte el Sharingan. Herido de muerte por Tobirama, deja sus ojos a Madara, que los usa para obtener el Mangekyō Eterno.",
  "characters[char-obito].aliases[0]": "Tobi",
  "characters[char-obito].aliases[1]": "Hombre Enmascarado",
  "characters[char-obito].rank": "Chunin / Cerebro de Akatsuki",
  "characters[char-obito].shortDescription": "Compañero de equipo de Kakashi, al que se creía muerto, y más tarde el cerebro detrás de Akatsuki como \"Tobi\".",
  "characters[char-obito].abilities[0]": "Sharingan",
  "characters[char-obito].abilities[1]": "Mangekyō Sharingan",
  "characters[char-obito].abilities[2]": "Kamui",
