  "routes[route-char-madara].group": "Personajes",
  "routes[route-char-madara].description": "Madara Uchiha, desde la fundación de Konoha con Hashirama hasta la batalla en el Valle del Fin, y desde el plan del Tsukuyomi Infinito confiado a Obito hasta su regreso en la Cuarta Guerra y la traición de Zetsu Negro.",
